{
  "commonPhenomenon": "支付查询显示成功，但异步通知未写入接收表，导致平台资金状态与通道结果不一致。",
  "facts": [
    {
      "statement": "交易结果查询成功，但异步支付通知尚未写入接收表。",
      "evidenceIds": [
        "E-015"
      ]
    }
  ],
  "differences": [
    {
      "description": "通道侧确认为支付成功，而平台侧因未收到或处理通知，资金状态未更新为成功，存在状态不一致。",
      "evidenceIds": [
        "E-015"
      ]
    }
  ],
  "possibleExplanations": [
    {
      "hypothesis": "支付成功回调缺失：通道发送了回调，但平台在接收、验签或入库过程中失败，导致通知未写入接收表。",
      "evidenceIds": [
        "E-015"
      ],
      "verification": "核查平台入口访问日志和商户通知应答记录，确认是否收到回调请求及处理结果；比对通道投递时间与平台接收时间。"
    },
    {
      "hypothesis": "平台与通道支付终态冲突：由于系统延迟或状态映射问题，导致当前快照显示平台未更新而通道已成功。",
      "evidenceIds": [
        "E-015"
      ],
      "verification": "获取新的只读查单结果，确认通道当前最终状态；检查平台内部状态采集时间和来源，排除旧快照干扰。"
    },
    {
      "hypothesis": "关单后收到支付成功通知：订单可能已被关单，随后才收到通道的成功通知，导致通知被丢弃或未正常入库。",
      "evidenceIds": [
        "E-015"
      ],
      "verification": "核对关单请求时间、通道对关单的应答以及该笔交易的实际支付时间，确认是否存在时序上的冲突。"
    }
  ],
  "checkSteps": [
    "使用商户订单号和通道交易号确认是同一笔交易。",
    "检查平台入口访问日志，确认是否有来自通道的回调请求到达。",
    "若收到回调，检查验签结果和处理逻辑日志，确认为何未写入接收表。",
    "若无回调记录，联系通道方确认是否发送过成功通知及发送时间。",
    "执行可信只读查单，确认通道当前的最终支付状态。",
    "比对各方的时间戳时区，确保时间对比准确。"
  ],
  "missingInformation": [
    "平台入口访问日志中关于该笔交易的通知接收记录。",
    "通道侧的回调投递记录或发送日志。",
    "平台内部处理该通知的详细业务日志（如验签、入库步骤）。",
    "该笔交易在平台内的当前完整状态流转历史。"
  ],
  "knowledgeCitations": [
    "lost-callback",
    "terminal-conflict",
    "late-success-after-close"
  ],
  "knowledgeOmissionReason": null
}
